function ParamField({
  name,
  schema,
  required,
  value,
  onChange,
}: {
  name: string;
  schema: ParamSchema;
  required: boolean;
  value: unknown;
  onChange: (v: unknown) => void;
}) {
  const label = schema.title ?? name;

  if (schema.type === "boolean") {
    return (
      <label className="checkbox">
        <input type="checkbox" checked={Boolean(value)} onChange={(e) => onChange(e.target.checked)} />
        {label}
      </label>
    );
  }

  let input: React.ReactNode;
  if (schema.type === "array") {
    input = (
      <input
        dir="auto"
        value={Array.isArray(value) ? value.join(", ") : ""}
        placeholder="Comma separated"
        onChange={(e) =>
          onChange(
            e.target.value
              .split(",")
              .map((s) => s.trim())
              .filter(Boolean),
          )
        }
        required={required}
      />
    );
  } else if (schema.type === "integer" || schema.type === "number") {
    input = (
      <input
        type="number"
        step={schema.type === "integer" ? 1 : "any"}
        value={value === undefined || value === null ? "" : String(value)}
        onChange={(e) => onChange(e.target.value === "" ? undefined : Number(e.target.value))}
        required={required}
      />
    );
  } else if (schema.format === "textarea") {
    input = (
      <textarea dir="auto" rows={4} value={String(value ?? "")} onChange={(e) => onChange(e.target.value)} required={required} />
    );
  } else {
    input = <input dir="auto" value={String(value ?? "")} onChange={(e) => onChange(e.target.value)} required={required} />;
  }

  return (
    <label>
      {label}
      {input}
      {schema.description && <span className="muted small">{schema.description}</span>}
    </label>
  );
}

