import type { Severity, Violation } from "../types";

export const SEVERITY_RANK: Record<Severity, number> = { info: 0, warning: 1, error: 2 };

/** A violation that points at a character range inside its block. */
export type SpanViolation = Violation & { start: number; end: number };

export interface Segment {
  text: string;
  violations: SpanViolation[];
}

export function hasSpan(v: Violation): v is SpanViolation {
  return v.start !== null && v.end !== null;
}

export function worstSeverity(violations: readonly Violation[]): Severity {
  return violations.reduce<Severity>(
    (worst, v) => (SEVERITY_RANK[v.severity] > SEVERITY_RANK[worst] ? v.severity : worst),
    "info",
  );
}

/**
 * Split text at every violation boundary so overlapping violations render correctly.
 * Each segment lists the violations that fully cover it. Offsets are clamped to the text.
 */
export function segmentText(text: string, violations: readonly Violation[]): Segment[] {
  const spans = violations.filter(hasSpan);
  const clamp = (n: number) => Math.max(0, Math.min(text.length, n));
  const cuts = new Set<number>([0, text.length]);
  for (const v of spans) {
    cuts.add(clamp(v.start));
    cuts.add(clamp(v.end));
  }
  const points = [...cuts].sort((a, b) => a - b);

  const segments: Segment[] = [];
  for (let i = 0; i < points.length - 1; i++) {
    const [a, b] = [points[i], points[i + 1]];
    if (a === b) continue;
    segments.push({
      text: text.slice(a, b),
      violations: spans.filter((v) => clamp(v.start) <= a && clamp(v.end) >= b),
    });
  }
  return segments;
}

/** Group violations by block; document-level ones (block_id null) are skipped. */
export function violationsByBlock(violations: readonly Violation[]): Map<number, Violation[]> {
  const map = new Map<number, Violation[]>();
  for (const v of violations) {
    if (v.block_id === null) continue;
    const list = map.get(v.block_id);
    if (list) list.push(v);
    else map.set(v.block_id, [v]);
  }
  return map;
}

export function countBySeverity(violations: readonly Violation[]): Partial<Record<Severity, number>> {
  const counts: Partial<Record<Severity, number>> = {};
  for (const v of violations) counts[v.severity] = (counts[v.severity] ?? 0) + 1;
  return counts;
}

import type { Block } from "../types";

export interface TableLayout {
  kind: "table";
  tableIndex: number;
  rows: number;
  cols: number;
  /** cells[row][col] -> blocks in that cell (0-based) */
  cells: Block[][][];
}

export type LayoutItem = { kind: "block"; block: Block } | TableLayout;

/** Paragraphs/headings stay in order; consecutive table-cell blocks are grouped back into tables. */
export function layoutBlocks(blocks: readonly Block[]): LayoutItem[] {
  const items: LayoutItem[] = [];
  let i = 0;
  while (i < blocks.length) {
    const block = blocks[i];
    const tableIndex = block.table_index;
    if (tableIndex === null) {
      items.push({ kind: "block", block });
      i++;
      continue;
    }
    const tableBlocks: Block[] = [];
    while (i < blocks.length && blocks[i].table_index === tableIndex) tableBlocks.push(blocks[i++]);
    items.push(buildTable(tableIndex, tableBlocks));
  }
  return items;
}

function buildTable(tableIndex: number, blocks: Block[]): TableLayout {
  const rows = Math.max(1, ...blocks.map((b) => b.row ?? 1));
  const cols = Math.max(1, ...blocks.map((b) => b.col ?? 1));
  const cells: Block[][][] = Array.from({ length: rows }, () => Array.from({ length: cols }, () => []));
  for (const b of blocks) cells[(b.row ?? 1) - 1][(b.col ?? 1) - 1].push(b);
  return { kind: "table", tableIndex, rows, cols, cells };
}

import { useCallback, useEffect, useState } from "react";
import { api, ApiError } from "../api";
import type { DocumentFull, Violation } from "../types";

export interface DocumentReportState {
  document: DocumentFull | null;
  /** null => document not checked yet */
  violations: Violation[] | null;
  checkedAt: string | null;
  loading: boolean;
  checking: boolean;
  error: string | null;
}

const EMPTY: DocumentReportState = {
  document: null,
  violations: null,
  checkedAt: null,
  loading: false,
  checking: false,
  error: null,
};

/** Loads the latest report for a document (or the bare document if never checked) and runs checks. */
export function useDocumentReport(documentId: number | null) {
  const [state, setState] = useState<DocumentReportState>(EMPTY);
  const [loadedId, setLoadedId] = useState<number | null>(null);

  // Reset during render when the selection changes (avoids setState inside an effect)
  if (loadedId !== documentId) {
    setLoadedId(documentId);
    setState({ ...EMPTY, loading: documentId !== null });
  }

  useEffect(() => {
    if (documentId === null) return;
    let cancelled = false;
    load(documentId)
      .then((next) => !cancelled && setState({ ...EMPTY, ...next }))
      .catch((err: unknown) => !cancelled && setState({ ...EMPTY, error: errorMessage(err) }));
    return () => {
      cancelled = true;
    };
  }, [documentId]);

  const runCheck = useCallback(async () => {
    if (documentId === null) return;
    setState((s) => ({ ...s, checking: true, error: null }));
    try {
      const report = await api.check(documentId);
      setState({
        ...EMPTY,
        document: report.document,
        violations: report.violations,
        checkedAt: report.checked_at,
      });
    } catch (err) {
      setState((s) => ({ ...s, checking: false, error: errorMessage(err) }));
    }
  }, [documentId]);

  return { ...state, runCheck };
}

async function load(documentId: number): Promise<Partial<DocumentReportState>> {
  try {
    const report = await api.latestReport(documentId);
    return { document: report.document, violations: report.violations, checkedAt: report.checked_at };
  } catch (err) {
    if (!(err instanceof ApiError && err.status === 404)) throw err;
    return { document: await api.document(documentId) };
  }
}

export function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

