import type { Block, DocumentFull, Report, Severity, Violation } from "../types";

export function block(overrides: Partial<Block> & Pick<Block, "id" | "text">): Block {
  return {
    kind: "paragraph",
    style: "Normal",
    heading_level: null,
    heading_context: null,
    label: `Paragraph ${overrides.id + 1}`,
    paragraph_index: overrides.id + 1,
    table_index: null,
    row: null,
    col: null,
    runs: [],
    ...overrides,
  };
}

export function violation(
  overrides: Partial<Violation> & Pick<Violation, "id">,
  severity: Severity = "error",
): Violation {
  return {
    rule_id: 1,
    rule_name: "Rule",
    severity,
    message: "Broken",
    block_id: 0,
    start: null,
    end: null,
    excerpt: "",
    location: "Paragraph 1",
    ...overrides,
  };
}

export const DOC: DocumentFull = {
  id: 1,
  filename: "spec.docx",
  size_bytes: 2048,
  uploaded_at: "2026-09-29T10:00:00Z",
  blocks: [
    block({ id: 0, text: "Performance", kind: "heading", heading_level: 1 }),
    block({ id: 1, text: "The detection range is 50 km.", heading_context: "Performance" }),
    block({ id: 2, text: "Parameter", table_index: 1, row: 1, col: 1, label: "Table 1, row 1, column 1" }),
    block({ id: 3, text: "2 seconds", table_index: 1, row: 1, col: 2, label: "Table 1, row 1, column 2" }),
  ],
};

export function report(violations: Violation[]): Report {
  return {
    check_id: 9,
    checked_at: "2026-09-29T10:05:00Z",
    document: DOC,
    violations,
    summary: { total: violations.length, by_severity: {}, rules_checked: 1 },
  };
}

import { describe, expect, it } from "vitest";
import { violation } from "../test/fixtures";
import { countBySeverity, segmentText, violationsByBlock, worstSeverity } from "./highlight";

const TEXT = "The detection range is 50 km.";

describe("segmentText", () => {
  it("returns the whole text when there are no violations", () => {
    expect(segmentText(TEXT, [])).toEqual([{ text: TEXT, violations: [] }]);
  });

  it("splits around a single span", () => {
    const v = violation({ id: "a", start: 23, end: 28 });
    const segs = segmentText(TEXT, [v]);
    expect(segs.map((s) => s.text)).toEqual(["The detection range is ", "50 km", "."]);
    expect(segs[1].violations).toEqual([v]);
  });

  it("handles overlapping spans", () => {
    const a = violation({ id: "a", start: 4, end: 19 }); // "detection range"
    const b = violation({ id: "b", start: 14, end: 28 }); // "range is 50 km"
    const segs = segmentText(TEXT, [a, b]);
    const overlap = segs.find((s) => s.text === "range");
    expect(overlap?.violations.map((v) => v.id)).toEqual(["a", "b"]);
    expect(segs.map((s) => s.text).join("")).toBe(TEXT);
  });

  it("ignores violations without a span and clamps out-of-range offsets", () => {
    const whole = violation({ id: "w" });
    const outOfRange = violation({ id: "o", start: 25, end: 999 });
    const segs = segmentText(TEXT, [whole, outOfRange]);
    expect(segs.map((s) => s.text)).toEqual(["The detection range is 50", " km."]);
    expect(segs[1].violations.map((v) => v.id)).toEqual(["o"]);
  });

  it("handles empty text", () => {
    expect(segmentText("", [violation({ id: "a", start: 0, end: 3 })])).toEqual([]);
  });
});

describe("worstSeverity / countBySeverity", () => {
  const list = [violation({ id: "1" }, "info"), violation({ id: "2" }, "error"), violation({ id: "3" }, "warning")];

  it("picks the most severe", () => {
    expect(worstSeverity(list)).toBe("error");
    expect(worstSeverity([])).toBe("info");
  });

  it("counts per severity", () => {
    expect(countBySeverity(list)).toEqual({ info: 1, error: 1, warning: 1 });
  });
});

describe("violationsByBlock", () => {
  it("groups by block and skips document-level violations", () => {
    const map = violationsByBlock([
      violation({ id: "1", block_id: 2 }),
      violation({ id: "2", block_id: null }),
      violation({ id: "3", block_id: 2 }),
    ]);
    expect([...map.keys()]).toEqual([2]);
    expect(map.get(2)?.map((v) => v.id)).toEqual(["1", "3"]);
  });
});

import { describe, expect, it } from "vitest";
import { block, DOC } from "../test/fixtures";
import { layoutBlocks } from "./layout";

describe("layoutBlocks", () => {
  it("keeps paragraphs in order and groups table cells", () => {
    const items = layoutBlocks(DOC.blocks);
    expect(items.map((i) => i.kind)).toEqual(["block", "block", "table"]);
    const table = items[2];
    if (table.kind !== "table") throw new Error("expected table");
    expect([table.rows, table.cols]).toEqual([1, 2]);
    expect(table.cells[0].map((cell) => cell.map((b) => b.text))).toEqual([["Parameter"], ["2 seconds"]]);
  });

  it("leaves empty grid positions for merged / missing cells", () => {
    const items = layoutBlocks([
      block({ id: 0, text: "A", table_index: 1, row: 1, col: 1 }),
      block({ id: 1, text: "C", table_index: 1, row: 1, col: 3 }),
    ]);
    const table = items[0];
    if (table.kind !== "table") throw new Error("expected table");
    expect(table.cells[0].map((cell) => cell.length)).toEqual([1, 0, 1]);
  });

  it("separates two tables that follow each other", () => {
    const items = layoutBlocks([
      block({ id: 0, text: "A", table_index: 1, row: 1, col: 1 }),
      block({ id: 1, text: "B", table_index: 2, row: 1, col: 1 }),
    ]);
    expect(items.map((i) => (i.kind === "table" ? i.tableIndex : -1))).toEqual([1, 2]);
  });

  it("handles an empty document", () => {
    expect(layoutBlocks([])).toEqual([]);
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { api, ApiError } from "./api";

function mockFetch(status: number, body?: unknown, statusText = "") {
  const fn = vi.fn().mockResolvedValue(
    new Response(body === undefined ? null : JSON.stringify(body), { status, statusText }),
  );
  vi.stubGlobal("fetch", fn);
  return fn;
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("api", () => {
  it("returns parsed JSON on success", async () => {
    const fetch = mockFetch(200, [{ id: 1 }]);
    await expect(api.rules()).resolves.toEqual([{ id: 1 }]);
    expect(fetch).toHaveBeenCalledWith("/api/rules", undefined);
  });

  it("sends JSON bodies", async () => {
    const fetch = mockFetch(200, {});
    await api.check(5);
    const [url, init] = fetch.mock.calls[0] as [string, RequestInit];
    expect(url).toBe("/api/documents/5/check");
    expect(init.method).toBe("POST");
    expect(init.headers).toEqual({ "Content-Type": "application/json" });
  });

  it("uses the server's detail message for errors", async () => {
    mockFetch(422, { detail: "Invalid regular expression" });
    const err = await api.rules().catch((e: unknown) => e);
    expect(err).toBeInstanceOf(ApiError);
    expect(err).toMatchObject({ status: 422, message: "Invalid regular expression" });
  });

  it("stringifies structured error details", async () => {
    mockFetch(422, { detail: [{ loc: ["body", "name"], msg: "required" }] });
    await expect(api.rules()).rejects.toThrow(/required/);
  });

  it("falls back to status text for non-JSON errors", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response("<html>", { status: 502, statusText: "Bad Gateway" })));
    await expect(api.rules()).rejects.toMatchObject({ status: 502, message: "Bad Gateway" });
  });

  it("handles 204 No Content on delete", async () => {
    mockFetch(204);
    await expect(api.deleteRule(3)).resolves.toBeUndefined();
  });

  it("propagates network failures", async () => {
    vi.stubGlobal("fetch", vi.fn().mockRejectedValue(new TypeError("Failed to fetch")));
    await expect(api.documents()).rejects.toThrow("Failed to fetch");
  });
});

import { act, renderHook, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { api, ApiError } from "../api";
import { DOC, report, violation } from "../test/fixtures";
import { useDocumentReport } from "./useDocumentReport";

afterEach(() => {
  vi.restoreAllMocks();
});

describe("useDocumentReport", () => {
  it("does nothing without a selection", () => {
    const spy = vi.spyOn(api, "latestReport");
    const { result } = renderHook(() => useDocumentReport(null));
    expect(result.current.document).toBeNull();
    expect(spy).not.toHaveBeenCalled();
  });

  it("loads the latest report", async () => {
    const v = violation({ id: "1-0", block_id: 1, start: 23, end: 28 });
    vi.spyOn(api, "latestReport").mockResolvedValue(report([v]));
    const { result } = renderHook(() => useDocumentReport(1));
    expect(result.current.loading).toBe(true);
    await waitFor(() => expect(result.current.document).toEqual(DOC));
    expect(result.current.violations).toEqual([v]);
    expect(result.current.loading).toBe(false);
  });

  it("falls back to the bare document when it was never checked", async () => {
    vi.spyOn(api, "latestReport").mockRejectedValue(new ApiError(404, "not checked"));
    vi.spyOn(api, "document").mockResolvedValue(DOC);
    const { result } = renderHook(() => useDocumentReport(1));
    await waitFor(() => expect(result.current.document).toEqual(DOC));
    expect(result.current.violations).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it("reports other load errors", async () => {
    vi.spyOn(api, "latestReport").mockRejectedValue(new ApiError(500, "boom"));
    const { result } = renderHook(() => useDocumentReport(1));
    await waitFor(() => expect(result.current.error).toBe("boom"));
  });

  it("runs a check and keeps the document when the check fails", async () => {
    vi.spyOn(api, "latestReport").mockRejectedValue(new ApiError(404, "not checked"));
    vi.spyOn(api, "document").mockResolvedValue(DOC);
    const check = vi.spyOn(api, "check").mockRejectedValueOnce(new ApiError(502, "All Gemini models are unavailable"));
    const { result } = renderHook(() => useDocumentReport(1));
    await waitFor(() => expect(result.current.document).toEqual(DOC));

    await act(() => result.current.runCheck());
    expect(result.current.error).toMatch(/unavailable/);
    expect(result.current.document).toEqual(DOC);
    expect(result.current.checking).toBe(false);

    check.mockResolvedValueOnce(report([]));
    await act(() => result.current.runCheck());
    expect(result.current.violations).toEqual([]);
    expect(result.current.error).toBeNull();
  });

  it("resets when the selection changes", async () => {
    vi.spyOn(api, "latestReport").mockResolvedValue(report([]));
    const { result, rerender } = renderHook(({ id }) => useDocumentReport(id), { initialProps: { id: 1 as number | null } });
    await waitFor(() => expect(result.current.document).not.toBeNull());
    rerender({ id: null });
    expect(result.current.document).toBeNull();
  });
});

import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { DOC, violation } from "../test/fixtures";
import ReportView from "./ReportView";

const scrollIntoView = vi.fn();

beforeEach(() => {
  scrollIntoView.mockClear();
  Element.prototype.scrollIntoView = scrollIntoView;
});

const SPAN = violation({ id: "1-0", rule_name: "No figures", message: "Reveals range", block_id: 1, start: 23, end: 28 });
const WHOLE = violation({ id: "2-0", rule_name: "Cell rule", message: "Bad cell", block_id: 3 }, "warning");
const DOC_LEVEL = violation({ id: "3-0", rule_name: "Banner", message: "Missing banner", block_id: null, location: "Whole document" });

function setup(violations = [SPAN, WHOLE, DOC_LEVEL]) {
  const onCheck = vi.fn();
  render(<ReportView document={DOC} violations={violations} checking={false} checkedAt={null} onCheck={onCheck} />);
  return { onCheck };
}

describe("ReportView", () => {
  it("highlights the exact span of a violation", () => {
    setup();
    const mark = screen.getByText("50 km");
    expect(mark.tagName).toBe("MARK");
    expect(mark).toHaveClass("sev-error");
    expect(mark).toHaveAttribute("title", "No figures: Reveals range");
  });

  it("flags the whole block when there is no span, inside the table", () => {
    setup();
    const cell = screen.getByText("2 seconds").closest("p");
    expect(cell).toHaveClass("flagged", "sev-warning");
    expect(cell?.closest("td")).not.toBeNull();
  });

  it("scrolls to the block and marks it active when a violation is clicked", async () => {
    setup();
    await userEvent.click(screen.getByRole("button", { name: /No figures/ }));
    expect(scrollIntoView).toHaveBeenCalledWith({ behavior: "smooth", block: "center" });
    expect(screen.getByText("50 km")).toHaveClass("active");
    expect(screen.getByRole("button", { name: /No figures/ })).toHaveClass("active");
  });

  it("does not scroll for document-level violations", async () => {
    setup();
    await userEvent.click(screen.getByRole("button", { name: /Banner/ }));
    expect(scrollIntoView).not.toHaveBeenCalled();
  });

  it("clicking a highlight selects its violation", async () => {
    setup();
    await userEvent.click(screen.getByText("50 km"));
    expect(screen.getByRole("button", { name: /No figures/ })).toHaveClass("active");
  });

  it("shows severity counts and runs a re-check", async () => {
    const { onCheck } = setup();
    const toolbar = screen.getByRole("heading", { name: "spec.docx" }).parentElement as HTMLElement;
    expect(within(toolbar).getByText("2 errors")).toBeInTheDocument();
    expect(within(toolbar).getByText("1 warning")).toBeInTheDocument();
    await userEvent.click(screen.getByRole("button", { name: "Re-check" }));
    expect(onCheck).toHaveBeenCalledOnce();
  });

  it("shows the empty and unchecked states", () => {
    const { unmount } = render(
      <ReportView document={DOC} violations={[]} checking={false} checkedAt={null} onCheck={vi.fn()} />,
    );
    expect(screen.getByText(/No violations found/)).toBeInTheDocument();
    unmount();
    render(<ReportView document={DOC} violations={null} checking={false} checkedAt={null} onCheck={vi.fn()} />);
    expect(screen.getByRole("button", { name: "Check document" })).toBeInTheDocument();
  });
});

