  --low: #a16207;
  --low-bg: #fef9c3;''')
s = s.replace("var(--error)", "var(--danger)").replace("var(--error-bg)", "var(--danger-bg)")
for old, new in (("error", "high"), ("warning", "medium"), ("info", "low")):
    s = s.replace(f".sev-{old}", f".sev-{new}")
# severity rules referenced danger after replace; fix the sev-high ones back to --high
s = re.sub(r"(\.sev-high[^{]*\{[^}]*?)var\(--danger(-bg)?\)", lambda m: m.group(1) + f"var(--high{m.group(2) or ''})", s)
s = re.sub(r"(\.sev-high[^{]*\{[^}]*?)var\(--danger(-bg)?\)", lambda m: m.group(1) + f"var(--high{m.group(2) or ''})", s)
for old, new in (("warning", "medium"), ("info", "low")):
    s = s.replace(f"var(--{old})", f"var(--{new})").replace(f"var(--{old}-bg)", f"var(--{new}-bg)")
open("src/styles.css", "w", encoding="utf-8", newline="\n").write(s)
EOF
