import { useState } from "react";
import type { SamplesState, TemplatesStatus } from "../hooks/useRuleTemplates";
import { cx } from "../lib/severity";
import { draftFromTemplate, usesAiQuota } from "../lib/templates";
import type { Rule, RuleCreate, RuleTemplate, RuleType, RuleUpdate } from "../types";
import RuleForm from "./RuleForm";
import TemplatePicker from "./TemplatePicker";
import { AiQuotaBadge, Button, ErrorNote, GlassPanel, SeverityDot } from "./ui";

export interface TemplatesView {
  templates: RuleTemplate[];
  status: TemplatesStatus;
  error: string | null;
  onRetry: () => void;
}

export interface SamplesView extends SamplesState {
  onLoad: () => void;
  onDismiss: () => void;
}

interface Props {
  rules: Rule[];
  types: RuleType[];
  loading: boolean;
  error: string | null;
  onDismissError: () => void;
  onCreate: (input: RuleCreate) => Promise<void>;
  onUpdate: (id: number, changes: RuleUpdate) => Promise<void>;
  onToggle: (rule: Rule) => void;
  onDelete: (rule: Rule) => void;
  templates: TemplatesView;
  samples: SamplesView;
}

type Editing =
  | { kind: "new"; initial: RuleCreate | null; source: string | null }
  | { kind: "edit"; rule: Rule };

export default function RulesPanel({
  rules,
  types,
  loading,
  error,
  onDismissError,
  onCreate,
  onUpdate,
  onToggle,
  onDelete,
  templates,
  samples,
}: Props) {
  const [editing, setEditing] = useState<Editing | null>(null);
  const [formKey, setFormKey] = useState(0);

  /** A new key per opening, so the form state resets when another template or rule is picked. */
  function open(next: Editing) {
    setEditing(next);
    setFormKey((k) => k + 1);
  }

  const typeLabel = (key: string) => types.find((t) => t.key === key)?.label ?? key;
  const templatesAvailable = templates.status !== "unavailable";

  return (
    <GlassPanel className="flex flex-col gap-3 p-5" aria-labelledby="rules-heading">
      <div className="flex items-center justify-between gap-2">
        <h2 id="rules-heading" className="text-base font-semibold text-slate-900">
          Rules
        </h2>
        <Button size="sm" onClick={() => open({ kind: "new", initial: null, source: null })} disabled={!types.length}>
          + New rule
        </Button>
      </div>

      <div className="flex flex-wrap items-start gap-2">
        <TemplatePicker
          templates={templates.templates}
          status={templates.status}
          error={templates.error}
          onRetry={templates.onRetry}
          onPick={(t) => open({ kind: "new", initial: draftFromTemplate(t), source: t.label })}
        />
        {templatesAvailable && (
          <Button variant="secondary" size="sm" onClick={samples.onLoad} disabled={samples.loading}>
            {samples.loading ? "Loading samples…" : "Load Sample Rules"}
          </Button>
        )}
      </div>
      {!templatesAvailable && (
        <p className="text-xs text-slate-600">Rule templates and sample rules are not available on this server.</p>
      )}
      {samples.message && (
        <p role="status" className="flex items-center justify-between rounded-2xl bg-emerald-50 px-3 py-2 text-sm text-emerald-900 ring-1 ring-emerald-200">
          Sample rules: {samples.message}
          <button type="button" className="rounded-full px-1.5 hover:bg-emerald-100" aria-label="Dismiss" onClick={samples.onDismiss}>
            ×
          </button>
        </p>
      )}
      {samples.error && <ErrorNote onDismiss={samples.onDismiss}>{samples.error}</ErrorNote>}
      {error && <ErrorNote onDismiss={onDismissError}>{error}</ErrorNote>}

      {editing && (
        <RuleForm
          key={formKey}
          types={types}
          rule={editing.kind === "edit" ? editing.rule : null}
          initial={editing.kind === "new" ? editing.initial : null}
          source={editing.kind === "new" ? editing.source : null}
          onCreate={onCreate}
          onUpdate={onUpdate}
          onDone={() => setEditing(null)}
        />
      )}

      {loading && <p className="text-sm text-slate-600">Loading rules…</p>}
      {!loading && !rules.length && !editing && (
        <p className="text-sm text-slate-600">No rules yet. Create one, pick a template, or load the sample rules.</p>
      )}
      <ul className="flex flex-col gap-1" aria-label="Rules list">
        {rules.map((rule) => (
          <li key={rule.id} className="flex items-start gap-3 rounded-2xl px-2 py-2 hover:bg-white/60">
            <input
              type="checkbox"
              role="switch"
              className="mt-0.5 size-4 shrink-0 accent-slate-900"
              checked={rule.enabled}
              onChange={() => onToggle(rule)}
              aria-label={`Enable ${rule.name}`}
            />
            <div className="min-w-0 flex-1">
              <div
                className={cx(
                  "flex items-center gap-2 text-sm font-medium",
                  rule.enabled ? "text-slate-900" : "text-slate-500",
                )}
              >
                <SeverityDot severity={rule.severity} />
                <span className="line-clamp-2 break-words" dir="auto" title={rule.name}>
                  {rule.name}
                </span>
                {!rule.enabled && <span className="shrink-0 text-xs font-normal text-slate-600">(off)</span>}
              </div>
              <div className="truncate text-xs text-slate-600" dir="auto">
                {typeLabel(rule.type)}
                {usesAiQuota(rule) && typeof rule.params.instruction === "string" && ` · ${rule.params.instruction}`}
              </div>
              <div className="mt-1 flex items-center gap-1">
                {usesAiQuota(rule) && <AiQuotaBadge />}
                <span className="flex-1" />
                <Button variant="ghost" size="sm" onClick={() => open({ kind: "edit", rule })} aria-label={`Edit ${rule.name}`}>
                  Edit
                </Button>
                <Button variant="danger" size="sm" onClick={() => onDelete(rule)} aria-label={`Delete ${rule.name}`}>
                  Delete
                </Button>
              </div>
            </div>
          </li>
        ))}
      </ul>
    </GlassPanel>
  );
}
import { useRef } from "react";
import { cx } from "../lib/severity";
import type { DocumentSummary } from "../types";
import { Button, ErrorNote, GlassPanel } from "./ui";

interface Props {
  documents: DocumentSummary[];
  selectedId: number | null;
  loading: boolean;
  uploading: boolean;
  error: string | null;
  onSelect: (id: number) => void;
  onUpload: (file: File) => void;
  onDelete: (doc: DocumentSummary) => void;
}

const DOCX_ACCEPT = ".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document";

export default function DocumentsPanel({
  documents,
  selectedId,
  loading,
  uploading,
  error,
  onSelect,
  onUpload,
  onDelete,
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <GlassPanel className="flex flex-col gap-3 p-5" aria-labelledby="documents-heading">
      <div className="flex items-center justify-between gap-2">
        <h2 id="documents-heading" className="text-base font-semibold text-slate-900">
          Documents
        </h2>
        <Button size="sm" onClick={() => inputRef.current?.click()} disabled={uploading}>
          {uploading ? "Uploading…" : "Upload .docx"}
        </Button>
        <input
          ref={inputRef}
          type="file"
          accept={DOCX_ACCEPT}
          hidden
          aria-label="Upload .docx file"
          data-testid="upload-input"
          onChange={(e) => {
            const file = e.target.files?.[0];
            e.target.value = "";
            if (file) onUpload(file);
          }}
        />
      </div>
      {error && <ErrorNote>{error}</ErrorNote>}
      {loading && <p className="text-sm text-slate-600">Loading documents…</p>}
      {!loading && !documents.length && <p className="text-sm text-slate-600">No documents uploaded yet.</p>}
      <ul className="flex flex-col gap-1" aria-label="Documents list">
        {documents.map((doc) => {
          const selected = doc.id === selectedId;
          return (
            <li
              key={doc.id}
              className={cx(
                "flex items-center gap-2 rounded-2xl pr-2",
                selected ? "bg-white text-slate-900 shadow-sm ring-2 ring-slate-900" : "text-slate-900 hover:bg-white/60",
              )}
            >
              <button
                type="button"
                className="min-w-0 flex-1 rounded-2xl px-3 py-2 text-left"
                aria-current={selected ? "true" : undefined}
                onClick={() => onSelect(doc.id)}
              >
                <span className="block truncate text-sm font-medium" dir="auto" title={doc.filename}>
                  {doc.filename}
                </span>
                <span className="block text-xs text-slate-600">
                  {(doc.size_bytes / 1024).toFixed(0)} KB · {new Date(doc.uploaded_at).toLocaleString()}
                </span>
              </button>
              <Button
                variant="danger"
                size="sm"
                onClick={() => onDelete(doc)}
                aria-label={`Delete ${doc.filename}`}
              >
                Delete
              </Button>
            </li>
          );
        })}
      </ul>
    </GlassPanel>
  );
}
import type { Severity } from "../types";

export const SEVERITY_LABEL: Record<Severity, string> = { high: "High", medium: "Medium", low: "Low" };

/**
 * Tailwind classes per severity: High red, Medium orange, Low yellow (ADR-010).
 * Full class strings on purpose, so Tailwind's scanner finds them.
 */
export const SEVERITY_CLASSES: Record<
  Severity,
  { mark: string; block: string; dot: string; chip: string; card: string; counter: string }
> = {
  high: {
    mark: "bg-red-200/90 decoration-red-600",
    block: "border-l-4 border-red-600 bg-red-50",
    dot: "bg-sev-high",
    chip: "border-red-300 bg-red-50 text-red-800 aria-pressed:bg-red-600 aria-pressed:border-red-600 aria-pressed:text-white",
    card: "border-l-red-600",
    counter: "bg-red-500/20 text-red-100 ring-red-400/40",
  },
  medium: {
    mark: "bg-orange-200/90 decoration-orange-600",
    block: "border-l-4 border-orange-500 bg-orange-50",
    dot: "bg-sev-medium",
    chip: "border-orange-300 bg-orange-50 text-orange-800 aria-pressed:bg-orange-600 aria-pressed:border-orange-600 aria-pressed:text-white",
    card: "border-l-orange-500",
    counter: "bg-orange-500/20 text-orange-100 ring-orange-400/40",
  },
  low: {
    mark: "bg-yellow-200 decoration-yellow-600",
    block: "border-l-4 border-yellow-500 bg-yellow-50",
    dot: "bg-yellow-500",
    chip: "border-yellow-300 bg-yellow-50 text-yellow-900 aria-pressed:bg-yellow-400 aria-pressed:border-yellow-500 aria-pressed:text-slate-950",
    card: "border-l-yellow-500",
    counter: "bg-yellow-400/20 text-yellow-100 ring-yellow-300/40",
  },
};

export function cx(...classes: (string | false | null | undefined)[]): string {
  return classes.filter(Boolean).join(" ");
}

