        <select className={inputClass} value={typeKey} onChange={(e) => changeType(e.target.value)} disabled={!!rule}>
          {!type && typeKey && <option value={typeKey}>{typeKey} (not supported)</option>}
          {types.map((t) => (
            <option key={t.key} value={t.key}>
              {t.label}
            </option>
