  return (
    <span className={cx("inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-semibold ring-1", SEVERITY_CLASSES[severity].counter)}>
      <SeverityDot severity={severity} />
      {SEVERITY_LABEL[severity]}
    </span>
  );
}

/** Marks rules that run through the LLM and therefore spend AI quota. */
export function AiQuotaBadge() {
  return (
    <span
      className="inline-flex shrink-0 items-center gap-1 rounded-full bg-violet-500/15 px-2 py-0.5 text-[0.7rem] font-semibold text-violet-200 ring-1 ring-violet-400/40"
      title="Checked by the AI model: every check with this rule enabled uses AI quota"
