import { cx, SEVERITY_CLASSES, SEVERITY_LABEL } from "../lib/severity";
import { SEVERITIES, type Severity } from "../types";
import { Icon, SeverityDot } from "./ui";

interface Props {
  documentName: string | null;
  /** null => no report for the selected document */
  counts: Partial<Record<Severity, number>> | null;
}

export default function TopBar({ documentName, counts }: Props) {
  return (
    <header className="flex flex-wrap items-center gap-x-6 gap-y-2 border-b border-slate-800 bg-slate-900 px-4 py-3 sm:px-6">
      <div className="flex items-center gap-2.5">
        <span className="flex size-8 items-center justify-center rounded-lg bg-indigo-500 text-white">
          <Icon name="shield" className="size-5" />
        </span>
        <h1 className="text-lg font-bold tracking-tight text-white">Ruleguarder</h1>
      </div>
      {documentName && (
        <p className="flex min-w-0 flex-1 items-center gap-2 text-sm text-slate-200" title={documentName}>
          <Icon name="document" className="size-4 shrink-0 text-slate-500" />
          <span className="truncate" dir="auto">
            {documentName}
          </span>
        </p>
      )}
      {counts && (
        <ul className="ml-auto flex items-center gap-5" aria-label="Violations by severity">
          {SEVERITIES.map((s) => (
            <li key={s} className={cx("inline-flex items-center gap-2 text-sm font-medium", SEVERITY_CLASSES[s].text)}>
              <SeverityDot severity={s} />
              {SEVERITY_LABEL[s]} <span className="font-semibold text-white tabular-nums">{counts[s] ?? 0}</span>
            </li>
          ))}
        </ul>
      )}
    </header>
  );
}

import { useRef } from "react";
import { cx } from "../lib/severity";
import type { DocumentSummary } from "../types";
import { Button, DeleteButton, ErrorNote, Icon, Panel, PanelHeader } from "./ui";

interface Props {
  documents: DocumentSummary[];
  selectedId: number | null;
  loading: boolean;
  uploading: boolean;
  error: string | null;
  onSelect: (id: number) => void;
  onUpload: (file: File) => void;
  onDelete: (doc: DocumentSummary) => void;
}

export const DOCX_ACCEPT = ".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document";

export function formatSize(bytes: number): string {
  return bytes >= 1024 * 1024 ? `${(bytes / 1024 / 1024).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

export default function DocumentsPanel({
  documents,
  selectedId,
  loading,
  uploading,
  error,
  onSelect,
  onUpload,
  onDelete,
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <Panel className="flex flex-col gap-4 p-4" aria-labelledby="documents-heading">
      <PanelHeader id="documents-heading" title="Documents" count={documents.length}>
        <Button size="sm" icon="upload" onClick={() => inputRef.current?.click()} disabled={uploading}>
          {uploading ? "Uploading…" : "Upload .docx"}
        </Button>
        <input
          ref={inputRef}
          type="file"
          accept={DOCX_ACCEPT}
          hidden
          aria-label="Upload .docx file"
          data-testid="upload-input"
          onChange={(e) => {
            const file = e.target.files?.[0];
            e.target.value = "";
            if (file) onUpload(file);
          }}
        />
      </PanelHeader>
      {error && <ErrorNote>{error}</ErrorNote>}
      {loading && <p className="text-sm text-slate-400">Loading documents…</p>}
      {!loading && !documents.length && (
        <p className="rounded-xl border border-dashed border-slate-700 px-4 py-6 text-center text-sm text-slate-400">
          No documents uploaded yet.
        </p>
      )}
      <ul className="flex flex-col gap-2" aria-label="Documents list">
        {documents.map((doc) => {
          const selected = doc.id === selectedId;
          return (
            <li
              key={doc.id}
              className={cx(
                "flex items-center gap-2 rounded-xl border pr-2 transition-colors",
                selected
                  ? "border-indigo-400/60 bg-indigo-500/15"
                  : "border-slate-700 bg-slate-800/50 hover:border-slate-500 hover:bg-slate-800",
              )}
            >
              <button
                type="button"
                className="flex min-w-0 flex-1 items-center gap-3 rounded-xl py-2.5 pl-3 text-left"
                aria-current={selected ? "true" : undefined}
                onClick={() => onSelect(doc.id)}
              >
                <Icon name="document" className={cx("size-5 shrink-0", selected ? "text-indigo-300" : "text-slate-500")} />
                <span className="min-w-0">
                  <span className="block truncate text-sm font-semibold text-white" dir="auto" title={doc.filename}>
                    {doc.filename}
                  </span>
                  <span className="block text-xs text-slate-400">
                    {formatSize(doc.size_bytes)} · {new Date(doc.uploaded_at).toLocaleString()}
                  </span>
                </span>
              </button>
              <DeleteButton compact name={doc.filename} onConfirm={() => onDelete(doc)} />
            </li>
          );
        })}
      </ul>
    </Panel>
  );
}

