def check_document(document_id: int, body: CheckRequest | None = None, db: Session = Depends(get_db)) -> ReportOut:
    """Run rules against the document and store the report.

    A rule that can't be checked is listed in `summary.failed_rules` and the others still count.
    Only when no rule could be checked at all does the request fail (502), so the latest
    completed report stays the one shown.

    Sync handler on purpose: FastAPI runs it in a worker thread, so a long LLM call
    doesn't block the event loop.
    """
    doc = _get_or_404(db, document_id)

    query = select(Rule).order_by(Rule.id)
    if body and body.rule_ids is not None:
        query = query.where(Rule.id.in_(body.rule_ids))
    else:
        query = query.where(Rule.enabled.is_(True))
    rules = list(db.scalars(query))
    if not rules:
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "No rules to check. Create or enable a rule first.")

    blocks = [Block.model_validate(b) for b in doc.blocks]
    run = CheckRun(document_id=doc.id, rule_ids=[r.id for r in rules])
    violations, summary = run_rules(rules, blocks, get_llm_provider)

    if summary.failed_rules and summary.rules_checked == 0:
        errors = list(dict.fromkeys(f.error for f in summary.failed_rules))
        run.status, run.error = "failed", " ".join(errors)
        db.add(run)
        db.commit()
        raise HTTPException(status.HTTP_502_BAD_GATEWAY, f"No rule could be checked. {run.error}")

    run.status = "completed"
    run.violations = [v.model_dump() for v in violations]
    run.summary = summary.model_dump()
    db.add(run)
    db.commit()
    return _report(doc, run)


@router.get("/{document_id}/report", response_model=ReportOut)
def latest_report(document_id: int, db: Session = Depends(get_db)) -> ReportOut:
    doc = _get_or_404(db, document_id)
    run = db.scalars(
        select(CheckRun)
        .where(CheckRun.document_id == doc.id, CheckRun.status == "completed")
        .order_by(CheckRun.created_at.desc(), CheckRun.id.desc())
        .limit(1)
    ).first()
    if run is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, "This document has not been checked yet")
    return _report(doc, run)


def _report(doc: Document, run: CheckRun) -> ReportOut:
    return ReportOut(
        check_id=run.id,
        checked_at=run.created_at,
        document=DocumentOut.model_validate(doc),
        violations=[Violation.model_validate(v) for v in run.violations],
        summary=ReportSummary.model_validate(run.summary),
    )


def _get_or_404(db: Session, document_id: int) -> Document:
def run_rules(
    rules: list[Rule], blocks: list[Block], llm: Callable[[], LlmProvider] | None
) -> tuple[list[Violation], ReportSummary]:
    """Run every rule against the document.

    Each rule is isolated: a rule that can't be checked (AI unavailable, stored params no longer
    valid, a regex that runs too long, a checker bug) is listed in `summary.failed_rules`, and the
    other rules' results are still returned. `llm` creates the provider; it is only called when
    there are AI rules, so a missing API key fails those rules and nothing else.
    """
    findings: dict[int, list[Finding]] = {}
    failed: dict[int, str] = {}
    llm_rules: list[tuple[Rule, LlmRule]] = []

    for rule in rules:
        try:
            rt = RULE_TYPES.get(rule.type)
            if rt is None:
                raise _RuleCheckError(f"Unknown rule type '{rule.type}'.")
            params = _stored_params(rule, rt.params_model)
            if rt.check is None:
                llm_rules.append((rule, LlmRule(rule.id, rule.name, params.instruction)))
                continue
            findings[rule.id] = list(rt.check(params, blocks))
        except _RuleCheckError as exc:
            failed[rule.id] = str(exc)
        except TimeoutError:
            failed[rule.id] = (
                f"The check took longer than {REGEX_TIMEOUT_SECONDS:g} s and was stopped. "
                "Simplify the regular expression."
            )
        except Exception:
            log.exception("Rule %s (%s) failed", rule.id, rule.type)
            failed[rule.id] = "Internal error while checking this rule."

    if llm_rules:
        try:
            if llm is None:
                raise LlmError("AI rules need an LLM provider, but none is configured.")
            findings.update(check_llm_rules(llm(), [lr for _, lr in llm_rules], blocks))
        except LlmError as exc:
            failed.update({rule.id: str(exc) for rule, _ in llm_rules})
        except Exception:
            log.exception("AI rules failed")
            failed.update({rule.id: "Internal error while running the AI check." for rule, _ in llm_rules})

    by_id = {b.id: b for b in blocks}
    violations: list[Violation] = []
    for rule in rules:
        for i, f in enumerate(findings.get(rule.id, [])):
            block = by_id.get(f.block_id) if f.block_id is not None else None
            violations.append(
                Violation(
                    id=f"{rule.id}-{i}",
                    rule_id=rule.id,
                    rule_name=rule.name,
                    severity=rule.severity,
                    message=f.message,
                    block_id=f.block_id,
                    start=f.start,
                    end=f.end,
                    excerpt=_excerpt(block, f.start, f.end),
                    location=_location(block),
                )
            )

    violations.sort(key=lambda v: (v.block_id is not None, v.block_id or 0, v.start or 0))
    summary = ReportSummary(
        total=len(violations),
        by_severity=dict(Counter(v.severity for v in violations)),
        rules_checked=len(rules) - len(failed),
        failed_rules=[FailedRule(rule_id=r.id, rule_name=r.name, error=failed[r.id]) for r in rules if r.id in failed],
    )
    return violations, summary


class _RuleCheckError(Exception):
    """A rule that can't run; the message is shown to the user."""


def _stored_params(rule: Rule, model: type[BaseModel]) -> Any:
    """Params as saved in the DB, validated again: a schema change can make an old rule invalid."""
    try:
        return model.model_validate(rule.params)
    except ValidationError as exc:
        details = "; ".join(f"{'.'.join(map(str, e['loc'])) or 'params'}: {e['msg']}" for e in exc.errors())
        raise _RuleCheckError(f"This rule's settings are no longer valid ({details}). Edit and save the rule.") from exc


